const item = $input.item;

const server = item.json.lastModifiedServer;
const client = item.json.lastModifiedClient;

if (!server) {
  throw new Error('Dropbox item missing lastModifiedServer');
}

const serverMs = Date.parse(server);
const clientMs = client ? Date.parse(client) : null;

const diffMs = (clientMs !== null) ? Math.abs(serverMs - clientMs) : null;

return {
  ...item,
  json: {
    ...item.json,
    recordedAtUtc: server,
    recordedAtUtcSource: 'dropbox.lastModifiedServer',
    recordedAtUtcEpochMs: serverMs,
    timestampDiffMs_serverVsClient: diffMs,
    timestampDiffMinutes_serverVsClient: diffMs !== null ? diffMs / 60000 : null,
    timestampWarning: (diffMs !== null && diffMs > 5 * 60000) ? true : false,
  }
};

const item = $input.item;
const utc = item.json.recordedAtUtc;
if (!utc) throw new Error('Missing recordedAtUtc');

const d = new Date(utc);
const yyyy = d.getUTCFullYear();
const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
const dd = String(d.getUTCDate()).padStart(2, '0');
const hh = String(d.getUTCHours()).padStart(2, '0');
const min = String(d.getUTCMinutes()).padStart(2, '0');

return {
  ...item,
  json: {
    ...item.json,
    parsedDate: `${yyyy}-${mm}-${dd}`,
    parsedDateTime: `${yyyy}-${mm}-${dd} ${hh}:${min} UTC`,
  }
};

const item = $input.item;
const windowMinutes = 15;

const center = item.json.recordedAtUtcEpochMs ?? Date.parse(item.json.recordedAtUtc);
if (!center) throw new Error('Missing recordedAtUtc');

const startMs = center - windowMinutes * 60 * 1000;
const endMs = center + windowMinutes * 60 * 1000;

return {
  ...item,
  json: {
    ...item.json,
    calendarWindowMinutes: windowMinutes,
    calendarWindowStartUtc: new Date(startMs).toISOString(),
    calendarWindowEndUtc: new Date(endMs).toISOString(),
  }
};

const rows = $input.all().map(i => i.json);
const category = ($('Find Calendar Match').item.json.categories?.[0] ?? '').trim();

const activeRows = rows.filter(r => String(r.active ?? 'TRUE').toLowerCase() !== 'false');
const fallback = activeRows.find(r => r.outlookCategory === '__PERSONAL__') || null;
const match = category
  ? (activeRows.find(r => r.outlookCategory === category) || fallback)
  : fallback;

if (!match) throw new Error(`No matching row and no __PERSONAL__ fallback. category="${category}"`);

// Build upload base URL
const defaultUploadBase = 'https://graph.microsoft.com/v1.0/me/drive/root:/n8n flows/Transcripts/Personal_Transcripts_Out';
let uploadBaseUrl;

if (match.sharePointSitePath) {
  // SharePoint format: sites/{hostname}:/{sitePath}:/drive/root:/{folderPath}
  const sitePath = match.sharePointSitePath.replace(/^\/+/, '').replace(/\/+$/, '');
  const folderPath = (match.folderPath || '').replace(/^\/+/, '').replace(/\/+$/, '');
  uploadBaseUrl = `https://graph.microsoft.com/v1.0/sites/compassrm.sharepoint.com:/${sitePath}:/drive/root:/${folderPath}`;
} else {
  uploadBaseUrl = defaultUploadBase;
}

return [{
  json: {
    ...match,
    matchedCategory: category,
    routingStatus: match.outlookCategory === category ? 'matched' : 'fallback',
    uploadBaseUrl,
  }
}];

const item = $input.item;

const raw = item.json.data ?? '';
if (item.json.error || !item.json.data) {
  return { ...item, json: { ...item.json, promptText: '', promptAvailable: false } };
}

let promptText = String(raw)
  .replace(/\\r\\n/g, '\n')
  .replace(/\\n/g, '\n')
  .replace(/\r\n/g, '\n')
  .trim();

const json = { ...item.json, promptText, promptAvailable: true };
delete json.data;

return { ...item, json };

const item = $input.item;

const raw = item.json.data ?? item.json.error ?? '';
if (item.json.error || !item.json.data) {
  return { ...item, json: { ...item.json, contextText: '', contextAvailable: false } };
}

let contextText = String(raw)
  .replace(/\\r\\n/g, '\n')
  .replace(/\\n/g, '\n')
  .replace(/\r\n/g, '\n')
  .trim();

const json = { ...item.json, contextText, contextAvailable: true };
delete json.data;

return { ...item, json };

const item = $input.item;

const binary = item.binary?.audio;
if (!binary) throw new Error('Missing item.binary.audio');

const buf = await this.helpers.getBinaryDataBuffer(0, 'audio');
const audioBase64 = buf.toString('base64');

return {
  json: {
    ...item.json,
    audioMimeType: binary.mimeType || 'audio/mp4',
    audioBase64,
    audioBase64Len: audioBase64.length,
  },
};

const j = $input.item.json;

const norm = (v) => {
  if (v === null || v === undefined) return '';
  return String(v).replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
};

const subject = norm(j.subject) || '(no subject)';
const startUtc = j.start?.dateTime ? String(j.start.dateTime) : '';
const endUtc   = j.end?.dateTime ? String(j.end.dateTime) : '';
const categories = Array.isArray(j.categories)
  ? j.categories.map(c => String(c).trim()).filter(Boolean).join(', ')
  : (j.categories ? String(j.categories) : '');
const attendees = Array.isArray(j.attendees)
  ? j.attendees.map(a => a?.emailAddress?.name || a?.emailAddress?.address).filter(Boolean).join(', ')
  : '[unknown]';

const filePrompt = norm(j.promptText);
const defaultPrompt = `Transcribe this meeting audio accurately and completely. Output a clean, readable transcript in markdown format.

Rules:
- Identify speakers by name using the attendees list and context provided. If a speaker cannot be identified, use Speaker 1, Speaker 2, etc.
- Include timestamps at natural breaks (every few minutes or at topic changes)
- Preserve the natural flow of conversation including false starts and corrections
- Mark unclear or inaudible sections as [inaudible]
- Do not summarize, analyze, or editorialize — just transcribe what was said
- Use proper nouns, names, and terminology from the provided context`;

const promptText = filePrompt || defaultPrompt;
const contextText = norm(j.contextText);

const geminiPrompt = norm(`
# PROMPT
${promptText}

# MEETING METADATA
Subject: ${subject}
Start (UTC): ${startUtc || '[unknown]'}
End (UTC): ${endUtc || '[unknown]'}
Categories: ${categories || '[none]'}
Attendees: ${attendees || '[unknown]'}

# CONTEXT
${contextText || '[none provided]'}
`);

return { json: { ...j, geminiPrompt } };

const item = $input.item;
const j = item.json ?? {};

const fail = (msg) => {
  const diag = {
    hasGeminiPrompt: !!j.geminiPrompt,
    geminiPromptLen: (j.geminiPrompt ? String(j.geminiPrompt).length : 0),
    hasAudioBase64: !!j.audioBase64,
    audioBase64Len: (j.audioBase64 ? String(j.audioBase64).length : 0),
    audioMimeType: j.audioMimeType ?? null,
    hasPromptText: !!j.promptText,
    hasContextText: !!j.contextText,
  };
  throw new Error(`${msg} | diag=${JSON.stringify(diag)}`);
};

if (!j || typeof j !== 'object' || Array.isArray(j)) {
  throw new Error(`Guardrail: expected item.json to be an object, got ${Array.isArray(j) ? 'array' : typeof j}`);
}

if (!j.geminiPrompt || String(j.geminiPrompt).trim().length < 50) {
  fail('Guardrail: geminiPrompt missing/too short');
}

if (!j.audioMimeType || String(j.audioMimeType).trim().length < 3) {
  fail('Guardrail: audioMimeType missing');
}

const mt = String(j.audioMimeType).toLowerCase();
if (!mt.startsWith('audio/')) {
  fail(`Guardrail: audioMimeType does not look like audio/* (got "${j.audioMimeType}")`);
}

if (!j.audioBase64 || String(j.audioBase64).trim().length < 5000) {
  fail('Guardrail: audioBase64 missing/too short (conversion likely failed)');
}

const a = String(j.audioBase64).trim().toLowerCase();
if (a === 'filesystem-v2' || a.startsWith('filesystem-')) {
  fail('Guardrail: audioBase64 is a filesystem pointer token, not real base64.');
}

if (!/^[a-z0-9+/=\s]+$/i.test(String(j.audioBase64).slice(0, 2000))) {
  fail('Guardrail: audioBase64 contains characters that do not look like base64');
}

return { json: j };

const j = $input.item.json ?? {};

const must = (cond, msg) => { if (!cond) throw new Error(`Build Gemini Request Body: ${msg}`); };

must(j.geminiPrompt && String(j.geminiPrompt).trim().length > 20, 'geminiPrompt missing/too short');
must(j.audioBase64 && String(j.audioBase64).trim().length > 5000, 'audioBase64 missing/too short');
must(j.audioMimeType && String(j.audioMimeType).trim().length > 3, 'audioMimeType missing/too short');

const temperature = 0.2;

const geminiRequestBody = {
  contents: [
    {
      role: 'user',
      parts: [
        { text: String(j.geminiPrompt) },
        {
          inlineData: {
            mimeType: String(j.audioMimeType),
            data: String(j.audioBase64),
          },
        },
      ],
    },
  ],
  generationConfig: { temperature },
};

return {
  json: {
    ...j,
    geminiRequestBody,
  },
};

const r = $input.item.json;

const text =
  r?.candidates?.[0]?.content?.parts
    ?.map(p => p.text ?? '')
    .join('\n')
    .trim();

if (!text) throw new Error('No text found in Gemini response');

return [{ json: { ...r, transcript: text } }];

const items = $input.all();
if (items.length === 0) return [];

items.sort((a, b) => {
  const dateA = new Date(a.json.lastModifiedServer || 0);
  const dateB = new Date(b.json.lastModifiedServer || 0);
  return dateB - dateA;
});

return [items[0]];
